Of": [{"$ref": "#/$defs/MarkdownBlock"}, {"$ref": "#/$defs/DiagramBlock"}, {"$ref": "#/$defs/ResourceBlock"}, {"$ref": "#/$defs/ExerciseBlock"}]}, "type": "array"}, "resource_requests": {"items": {"$ref": "#/$defs/ResourceRequest"}, "type": "array"}}, "required": ["schema_version", "target_key", "overview", "blocks", "resource_requests"], "type": "object"}
